import React, { useEffect } from 'react';
import { motion } from 'framer-motion';

const WorkerSplash = ({ onComplete }) => {
  useEffect(() => {
    // Keep the Lenin Blue screen visible for 3 seconds of "wow"
    const timer = setTimeout(() => {
      onComplete();
    }, 3000);
    return () => clearTimeout(timer);
  }, [onComplete]);

  return (
    <div className="flex flex-col items-center">
      <motion.h1 
        initial={{ scale: 0.8, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        transition={{ duration: 1 }}
        className="text-[#FFF24D] text-9xl font-[1000] italic tracking-tighter"
      >
        T2T
      </motion.h1>
      <div className="mt-4 h-1 w-24 bg-[#AB1717] animate-pulse" />
    </div>
  );
};

export default WorkerSplash;
